const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const reject = (reason) => [{ json: { valid: false, reason } }];

const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) return reject('N8N_WEBHOOK_SECRET is not set');

const headers = $input.first().json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');

if (!/^\d{9,12}$/.test(timestamp)) return reject('missing or malformed timestamp');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('stale timestamp (possible replay)');
if (!/^sha256=[0-9a-f]{64}$/i.test(signature)) return reject('missing or malformed signature');

// Verify over the exact raw bytes that were sent, never over re-serialised JSON.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest();
const given = Buffer.from(signature.slice(7), 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return reject('bad signature');

let payload;
try { payload = JSON.parse(raw); } catch { return reject('body is not valid JSON'); }
if (!payload.eventId || !payload.event || !payload.loan || !payload.recipient) return reject('payload is missing required fields');

return [{ json: { valid: true, payload } }];

// n8n may be called more than once for the same event (Convex retries on timeouts).
// Event ids are deterministic (`<loanId>:<event>`), so "seen before" is a simple lookup.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const cutoff = Date.now() - 7 * 24 * 3600 * 1000;
for (const [id, at] of Object.entries(store.seen)) if (at < cutoff) delete store.seen[id];

const { payload } = $input.first().json;
return [{ json: { payload, duplicate: Boolean(store.seen[payload.eventId]) } }];

const { payload } = $input.first().json;
const { event, loan, recipient } = payload;
const clean = (s) => String(s ?? '').replace(/[\r\n]+/g, ' ').trim().slice(0, 80);
const name = clean(recipient.displayName) || 'there';
const tool = clean(loan.toolName);
const dates = loan.startDate === loan.endDate ? loan.startDate : `${loan.startDate} to ${loan.endDate}`;

const templates = {
  'loan.requested': [`New request for your ${tool}`, `Hi ${name}, a neighbor would like to borrow your ${tool} (${dates}). Open LendLoop to approve or decline.`],
  'loan.approved':  [`Your request for ${tool} was approved`, `Hi ${name}, good news: you can borrow the ${tool} (${dates}). Please return it on time.`],
  'loan.declined':  [`Your request for ${tool} was declined`, `Hi ${name}, unfortunately the ${tool} is not available for ${dates}. Have a look at other listings on LendLoop.`],
  'loan.returned':  [`${tool} marked as returned`, `Hi ${name}, the ${tool} was marked as returned. Thanks for being a good neighbor!`],
  'loan.cancelled': [`Request for ${tool} was cancelled`, `Hi ${name}, the request for the ${tool} (${dates}) was cancelled.`],
};
const t = templates[event];
if (!t) throw new Error(`Unknown event type: ${clean(event)}`);

return [{ json: { payload, message: { subject: t[0], text: t[1] } } }];

// Notification channel. Default: log it (visible in the n8n execution).
// If NOTIFY_WEBHOOK_URL is set (Slack / Mattermost / Discord-compatible), also POST it there.
const deliver = async (message) => {
  console.log(`[lendloop notification] ${message.subject} :: ${message.text.replace(/\n/g, ' ')}`);
  const url = $env.NOTIFY_WEBHOOK_URL;
  if (!url) return 'log';
  await this.helpers.httpRequest({
    method: 'POST', url, json: true, timeout: 8000,
    body: { text: `*${message.subject}*\n${message.text}`, content: `**${message.subject}**\n${message.text}` },
  });
  return 'webhook';
};

const { payload, message } = $input.first().json;
const channel = await deliver(message);
return [{ json: { payload, channel } }];

const { payload, channel } = $input.first().json;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
store.seen[payload.eventId] = Date.now();   // only after a successful delivery, so a failed attempt can be retried
return [{ json: { status: 'delivered', eventId: payload.eventId, channel } }];
